222	    private static final RowMapper<Claim> ROW = (rs, i) -> new Claim(rs.getLong("id"), rs.getLong("person"),
223	            rs.getBigDecimal("amount").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
224	            rs.getDate("claimed_on").toLocalDate().toString(), rs.getString("note"),
225	            ClaimStatus.valueOf(rs.getString("status")), rs.getObject("number_on_sheet", Integer.class),
226	            rs.getBigDecimal("settled_due") == null ? null
227	                    : rs.getBigDecimal("settled_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
228	            rs.getString("opened_by"), rs.getBoolean("stated"),
229	            rs.getBigDecimal("stated_due") == null ? null
230	                    : rs.getBigDecimal("stated_due").setScale(2, RoundingMode.UNNECESSARY).toPlainString());
231	
232	    private static final String COLUMNS = "SELECT id, person, amount, claimed_on, note, status, number_on_sheet, settled_due, opened_by, stated, stated_due FROM claim";
233	
234	    private final JdbcTemplate jdbc;
235	
236	    public Claims(JdbcTemplate jdbc) {
237	        this.jdbc = jdbc;
238	    }
239	
240	    /** Every claim on the sheet, newest first. */
241	    public List<Claim> list(String sheet) {
242	        return jdbc.query(COLUMNS + " WHERE sheet = ? ORDER BY id DESC", ROW, sheet);
243	    }
244	
245	    public Claim find(String sheet, long id) {
246	        List<Claim> found = jdbc.query(COLUMNS + " WHERE sheet = ? AND id = ?", ROW, sheet, id);
247	        return found.isEmpty() ? null : found.get(0);
248	    }
249	
250	    public void add(String sheet, long person, ClaimInput input) {
251	        jdbc.update("INSERT INTO claim (sheet, person, amount, claimed_on, note) VALUES (?, ?, ?, ?, ?)", sheet, person,
252	                input.amount(), Date.valueOf(input.date()), input.note());
253	    }
254	
255	    public void update(String sheet, long id, ClaimInput input) {
256	        jdbc.update("UPDATE claim SET amount = ?, claimed_on = ?, note = ? WHERE sheet = ? AND id = ?", input.amount(),
257	                Date.valueOf(input.date()), input.note(), sheet, id);
258	    }
259	
260	    /** Moves the claim from one status to another: false when it no longer has the status it was read with. */
261	    public boolean changeStatus(String sheet, long id, ClaimStatus from, ClaimStatus to) {
262	        return jdbc.update("UPDATE claim SET status = ? WHERE sheet = ? AND id = ? AND status = ?", to.name(), sheet,
263	                id, from.name()) == 1;
264	    }
265	
266	    /** Fixes the claim's due as it is settled, or leaves none with null. */
267	    public void setSettledDue(String sheet, long id, BigDecimal due) {
268	        jdbc.update("UPDATE claim SET settled_due = ? WHERE sheet = ? AND id = ?", due, sheet, id);
269	    }
270	
271	    /** Binds the claim to a statement's figure (null when its grade had no rate), or unbinds it when not stated. */
272	    public void setStated(String sheet, long id, boolean stated, BigDecimal due) {
273	        jdbc.update("UPDATE claim SET stated = ?, stated_due = ? WHERE sheet = ? AND id = ?", stated, due, sheet, id);
274	    }
275	
276	    /** Records the user who opened the claim. */
277	    public void setOpenedBy(String sheet, long id, String user) {
278	        jdbc.update("UPDATE claim SET opened_by = ? WHERE sheet = ? AND id = ?", user, sheet, id);
279	    }
280	
281	    /** Sets the claim's number on the sheet, or clears it with null. */
282	    public void setNumber(String sheet, long id, Integer number) {
283	        jdbc.update("UPDATE claim SET number_on_sheet = ? WHERE sheet = ? AND id = ?", number, sheet, id);
284	    }
285	
286	    /**
287	     * Takes the sheet's next claim number: 1 first, then 2, and so on. The counter row stays locked until the
288	     * transaction ends, so two claims opened at once get different numbers.
289	     */
290	    public int nextNumber(String sheet) {
291	        while (true) {
292	            if (jdbc.update("UPDATE claim_number SET last_number = last_number + 1 WHERE sheet = ?", sheet) == 1) {
293	                return jdbc.queryForObject("SELECT last_number FROM claim_number WHERE sheet = ?", Integer.class,
294	                        sheet);
295	            }
296	            try {
297	                jdbc.update("INSERT INTO claim_number (sheet, last_number) VALUES (?, 1)", sheet);
298	                return 1;
299	            } catch (DuplicateKeyException raced) {
300	                // Another user took the sheet's first number at the same moment: take the one after it.
301	            }
302	        }
303	    }
304	}
