333	/** Where a claim is in its life: only OPEN and SETTLED claims count toward the totals. */
334	public enum ClaimStatus {
335	    DRAFT, OPEN, SETTLED, VOID;
336	
337	    /** The status a change takes this claim to, or null when the change is not allowed from here. */
338	    public ClaimStatus after(ClaimStatusChange change) {
339	        return switch (change) {
340	            case OPEN -> this == DRAFT ? OPEN : null;
341	            case SETTLE -> this == OPEN ? SETTLED : null;
342	            case VOID -> this == DRAFT || this == OPEN ? VOID : null;
343	        };
344	    }
345	}
