572	import java.util.List;
573	import org.springframework.dao.DuplicateKeyException;
574	import org.springframework.jdbc.core.JdbcTemplate;
575	import org.springframework.jdbc.core.RowMapper;
576	import org.springframework.jdbc.support.GeneratedKeyHolder;
577	import org.springframework.stereotype.Repository;
578	
579	/** The people kept per sheet. */
580	@Repository
581	public class People {
582	
583	    private static final RowMapper<Person> ROW = (rs, i) -> new Person(rs.getLong("id"), rs.getString("name"),
584	            rs.getString("grade"), rs.getLong("version"));
585	
586	    private final JdbcTemplate jdbc;
587	
588	    public People(JdbcTemplate jdbc) {
589	        this.jdbc = jdbc;
590	    }
591	
592	    /** Everyone on the sheet, in the order they were added. */
593	    public List<Person> list(String sheet) {
594	        return jdbc.query("SELECT id, name, grade, version FROM person WHERE sheet = ? ORDER BY id", ROW, sheet);
595	    }
596	
597	    public Person find(String sheet, long id) {
598	        List<Person> found = jdbc.query("SELECT id, name, grade, version FROM person WHERE sheet = ? AND id = ?", ROW,
599	                sheet, id);
600	        return found.isEmpty() ? null : found.get(0);
601	    }
602	
603	    /** Whether someone on the sheet other than {@code except} has this name, ignoring case. */
604	    private boolean nameTaken(String sheet, String name, Long except) {
605	        Integer taken = jdbc.queryForObject(
606	                "SELECT COUNT(*) FROM person WHERE sheet = ? AND name_key = LOWER(?) AND (? IS NULL OR id <> ?)",
607	                Integer.class, sheet, name, except, except);
608	        return taken != null && taken > 0;
609	    }
610	
611	    public Person add(String sheet, String name, String grade) throws DuplicatePersonNameException {
612	        if (nameTaken(sheet, name, null)) {
613	            throw new DuplicatePersonNameException(name);
614	        }
615	        GeneratedKeyHolder keys = new GeneratedKeyHolder();
616	        try {
617	            insert(sheet, name, grade, keys);
618	        } catch (DuplicateKeyException e) {
619	            throw new DuplicatePersonNameException(name);
620	        }
621	        return new Person(keys.getKey().longValue(), name, grade, 0);
622	    }
623	
624	    private void insert(String sheet, String name, String grade, GeneratedKeyHolder keys) {
625	        jdbc.update(con -> {
626	            var ps = con.prepareStatement("INSERT INTO person (sheet, name, grade) VALUES (?, ?, ?)",
627	                    new String[] { "id" });
628	            ps.setString(1, sheet);
629	            ps.setString(2, name);
630	            ps.setString(3, grade);
631	            return ps;
632	        }, keys);
633	    }
634	
635	    /** Save the person over the version it carries, raising the version; refused when it has moved on. */
636	    public void update(String sheet, Person person) throws DuplicatePersonNameException, StalePersonException {
637	        if (nameTaken(sheet, person.name(), person.id())) {
638	            throw new DuplicatePersonNameException(person.name());
639	        }
640	        int updated;
641	        try {
642	            updated = jdbc.update(
643	                    "UPDATE person SET name = ?, grade = ?, version = version + 1 WHERE sheet = ? AND id = ? AND version = ?",
644	                    person.name(), person.grade(), sheet, person.id(), person.version());
645	        } catch (DuplicateKeyException e) {
646	            throw new DuplicatePersonNameException(person.name());
647	        }
648	        if (updated == 0) {
649	            throw new StalePersonException(person.id());
650	        }
651	    }
652	}
