778	 * (yyyy-MM-dd; null when it applies from the beginning of time).
779	 */
780	public record Rate(String grade, String pct, String from) {
781	
782	    /**
783	     * The percent the grade's rates give on a date: the one whose from-date is the latest on or before it, or null
784	     * when the date is before every rate the grade has.
785	     */
786	    public static String on(List<Rate> rates, String grade, LocalDate date) {
787	        return rates.stream().filter((r) -> r.grade().equals(grade))
788	                .filter((r) -> r.from() == null || !LocalDate.parse(r.from()).isAfter(date))
789	                .max(Comparator.comparing((Rate r) -> r.from() == null ? LocalDate.MIN : LocalDate.parse(r.from())))
790	                .map(Rate::pct).orElse(null);
791	    }
792	
793	    /** An amount times a percent, divided by 100, in hundredths rounded half to even; null when there is no rate. */
794	    public static BigDecimal due(String amount, String pct) {
795	        return pct == null ? null
796	                : new BigDecimal(amount).multiply(new BigDecimal(pct)).movePointLeft(2).setScale(2,
797	                        RoundingMode.HALF_EVEN);
798	    }
799	}
