1082	/**
1083	 * Takes a statement of the person: records their due-total now, binds each of their counting claims to the figure
1084	 * it has now and unbinds the rest. The due-total is n/a when their grade has no rate on the sheet's today, unless a
1085	 * counting claim keeps a figure (settled or bound): then it is the figures there are.
1086	 */
1087	public class TakeStatement {
1088	    public void take(@PathVariable("sheet") String sheet, @RequestParam("user") String user, @Val Person person,
1089	            Claims claims, Rates rates, Statements statements, SheetClock clock, Audit audit) {
1090	        LocalDate today = clock.today(sheet);
1091	        List<Rate> sheetRates = rates.list(sheet);
1092	        List<Claim> mine = claims.list(sheet).stream().filter((c) -> c.person() == person.id()).toList();
1093	        boolean na = Rate.on(sheetRates, person.grade(), today) == null
1094	                && mine.stream().noneMatch((c) -> c.counts() && c.fixed());
1095	        BigDecimal total = BigDecimal.ZERO.setScale(2);
1096	        int count = 0;
1097	        for (Claim claim : mine) {
1098	            if (claim.counts()) {
1099	                BigDecimal due = claim.due(sheetRates, person.grade());
1100	                claims.setStated(sheet, claim.id(), true, due);
1101	                total = due == null ? total : total.add(due);
1102	                count++;
1103	            } else if (claim.stated()) {
1104	                claims.setStated(sheet, claim.id(), false, null);
1105	            }
1106	        }
1107	        BigDecimal dueTotal = na ? null : total;
1108	        statements.add(sheet, person.id(), dueTotal, today);
1109	        audit.record("STATEMENT sheet=" + sheet + " by=" + user + " name=" + person.name() + " due-total="
1110	                + (dueTotal == null ? "n/a" : dueTotal.toPlainString()) + " claims=" + count);
1111	    }
1112	}
